-- ============================================================
-- UTILITY FUNCTIONS
-- ============================================================

-- Lay danh sach cac map co the di den tu map hien tai
-- @param nMapID: ID ban do hien tai
-- @return table cac map ID co the di den, hoac nil
function GetConnectedMaps(nMapID)
	if tbMapGraph[nMapID] then
		return tbMapGraph[nMapID]
	end
	return nil
end

-- Kiem tra 2 map co lien ket truc tiep khong
-- @param nFromMapID: Map xuat phat
-- @param nToMapID: Map dich
-- @return 1 neu co lien ket, 0 neu khong
function IsMapConnected(nFromMapID, nToMapID)
	local tbTargets = tbMapGraph[nFromMapID]
	if tbTargets then
		for _, nID in pairs(tbTargets) do
			if nID == nToMapID then
				return 1
			end
		end
	end
	return 0
end

-- Lay ten ban do theo ID
-- @param nMapID: ID ban do
-- @return ten ban do hoac "Unknown"
function GetMapNameByID(nMapID)
	if tbMapName[nMapID] then
		return tbMapName[nMapID]
	end
	return "Unknown"
end

-- Lay loai ban do theo ID
-- @param nMapID: ID ban do
-- @return loai ban do (City, Field, Cave, Tong, Country, Capital)
function GetMapTypeByID(nMapID)
	if tbMapType[nMapID] then
		return tbMapType[nMapID]
	end
	return "Unknown"
end

-- Tim duong di ngan nhat giua 2 map (BFS)
-- @param nFromMapID: Map xuat phat
-- @param nToMapID: Map dich
-- @return table chua duong di (danh sach map ID), hoac nil neu khong tim thay
function FindPath(nFromMapID, nToMapID)
	if nFromMapID == nToMapID then
		return { nFromMapID }
	end

	local tbVisited = {}
	local tbQueue = {}
	local tbParent = {}

	table.insert(tbQueue, nFromMapID)
	tbVisited[nFromMapID] = 1
	tbParent[nFromMapID] = -1

	while #tbQueue > 0 do
		local nCurrent = tbQueue[1]
		table.remove(tbQueue, 1)

		local tbTargets = tbMapGraph[nCurrent]
		if tbTargets then
			for _, nNext in pairs(tbTargets) do
				if not tbVisited[nNext] then
					tbVisited[nNext] = 1
					tbParent[nNext] = nCurrent
					if nNext == nToMapID then
						-- Truy nguoc duong di
						local tbPath = {}
						local nNode = nToMapID
						while nNode ~= -1 do
							table.insert(tbPath, 1, nNode)
							nNode = tbParent[nNode]
						end
						return tbPath
					end
					table.insert(tbQueue, nNext)
				end
			end
		end
	end

	return nil
end

-- In duong di giua 2 map (de debug)
-- @param nFromMapID: Map xuat phat
-- @param nToMapID: Map dich
function PrintPath(nFromMapID, nToMapID)
	local tbPath = FindPath(nFromMapID, nToMapID)
	if tbPath then
		local szResult = "Duong di: "
		for i, nID in ipairs(tbPath) do
			if i > 1 then
				szResult = szResult .. " -> "
			end
			szResult = szResult .. GetMapNameByID(nID) .. "(" .. nID .. ")"
		end
		print(szResult)
	else
		print("Khong tim thay duong di tu " .. GetMapNameByID(nFromMapID) .. " den " .. GetMapNameByID(nToMapID))
	end
end

-- Lay tat ca map thuoc 1 loai (City, Field, Cave, etc)
-- @param szType: Loai ban do
-- @return table chua danh sach map ID
function GetMapsByType(szType)
	local tbResult = {}
	for nID, szMapType in pairs(tbMapType) do
		if szMapType == szType then
			table.insert(tbResult, nID)
		end
	end
	table.sort(tbResult)
	return tbResult
end

-- Dem so luong map ket noi voi 1 map (bac cua node)
-- @param nMapID: ID ban do
-- @return so luong map ket noi
function GetMapConnectionCount(nMapID)
	if tbMapGraph[nMapID] then
		return #tbMapGraph[nMapID]
	end
	return 0
end
